    try { p.push(f); } catch (e) { lastError = `push: ${e?.message ?? e}`; }
  },
  onStderr: (s2) => { if (process.env.DSH_SEE_NOW_DEBUG) log(s2.trim()); },
});

watch:
export function scorePair(prev, cur) {
  let sum = 0;
  for (let i = 0; i < cur.length; i += 3) {
    const dh = Math.abs(cur[i] - prev[i]);
    const hueDiff = Math.min(dh, 255 - dh);
    const hueWeight = Math.min(cur[i + 1], prev[i + 1]) / 255;
    sum += hueDiff * hueWeight
      + Math.abs(cur[i + 1] - prev[i + 1])
      + Math.abs(cur[i + 2] - prev[i + 2]);
  }
  return sum / ((cur.length / 3) * 3);
}

acc += s;
if (acc >= integralNeed() && entry.t - lastBound >= o.markMinGap) {
  // 只有**真的录进去**才清零。被去重挡掉时保留累积值 —— 否则这一段的运动量
  // 白攒了，下一个采样点要重新等一整轮（实测会让出帧间隔凭空翻倍）。
  if (keep(entry, 'mark')) acc = 0;
  return;
}
let floorSec = o.silentFloorSec;
if (o.floorGapK > 0 && gapEwma > 0) {
  floorSec = Math.min(o.floorMax, Math.max(o.floorMin, o.floorGapK * gapEwma));
}
if (entry.t - lastBound >= floorSec) keep(entry, 'floor');

